const IMG={"logo": "data:image/png;base64,", "atrinika": "data:image/jpeg;base64,", "flag": "data:image/png;base64,", "hero": "data:image/jpeg;base64,", "match1": "data:image/jpeg;base64,", "match2": "data:image/jpeg;base64,", "team": "data:image/jpeg;base64,", "news1": "data:image/jpeg;base64,", "news2": "data:image/jpeg;base64,", "news3": "data:image/jpeg;base64,", "news4": "data:image/jpeg;base64,"};

document.querySelectorAll('[data-img]').forEach(el=>{let k=el.dataset.img;if(IMG[k])el.src=IMG[k]});
document.querySelectorAll('[data-year]').forEach(el=>el.textContent=new Date().getFullYear());
